<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/PayrollExportService.php';if(!PayrollRepository::canManage()&&!Auth::can('payroll.view_all')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$periodId=(int)($_GET['period_id']??0);$period=$periodId?Database::fetch('SELECT * FROM payroll_periods WHERE id=?',[$periodId]):null;$slips=$period?Database::fetchAll("SELECT id,employee_no FROM payroll_slips WHERE period_id=? AND status<>'cancelled' ORDER BY id",[$periodId]):[];$action=(string)($_GET['action']??'');if($period&&in_array($action,['group_pdf','zip'],true)){$fragments=[];foreach($slips as $s){try{$fragments[]=PayrollSlipRenderer::fragment(PayrollSlipRenderer::data((int)$s['id'],false,true));}catch(Throwable $e){}}$html='<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>.payroll-paper{page-break-after:always}</style></head><body class="payroll-output">'.implode('',$fragments).'</body></html>';if($action==='group_pdf'){$bytes=PayrollExportService::bytes($html);if($bytes!==null){Database::execute('INSERT INTO payroll_exports(period_id,export_type,generated_by,generated_at) VALUES(?,?,?,NOW())',[$periodId,'group_pdf',(int)Auth::user()['id']]);header('Content-Type:application/pdf');header('Content-Disposition:attachment; filename="payroll-'.$period['period_key'].'.pdf"');echo $bytes;exit;}header('Content-Type:text/html; charset=utf-8');echo str_replace('</body>','<script>addEventListener("load",()=>print())</script></body>',$html);exit;}if(!class_exists('ZipArchive')){flash('افزونه ZIP روی سرور فعال نیست.','danger');redirect('/admin/payroll-export.php?period_id='.$periodId);}$zipPath=tempnam(sys_get_temp_dir(),'sobhan-payroll-');$zip=new ZipArchive();if($zip->open($zipPath,ZipArchive::OVERWRITE)!==true){flash('ساخت فایل ZIP انجام نشد.','danger');redirect('/admin/payroll-export.php?period_id='.$periodId);}foreach($slips as $s){$data=PayrollSlipRenderer::data((int)$s['id'],false,true);$bytes=PayrollExportService::bytes(PayrollSlipRenderer::page($data));if($bytes===null){$zip->close();@unlink($zipPath);flash('کتابخانه PDF روی سرور نصب نیست؛ از خروجی گروهی چاپ استفاده کنید.','danger');redirect('/admin/payroll-export.php?period_id='.$periodId);}$zip->addFromString('payroll-'.$s['employee_no'].'-'.$period['period_key'].'.pdf',$bytes);}$zip->close();Database::execute('INSERT INTO payroll_exports(period_id,export_type,generated_by,generated_at) VALUES(?,?,?,NOW())',[$periodId,'zip',(int)Auth::user()['id']]);header('Content-Type:application/zip');header('Content-Disposition:attachment; filename="payroll-'.$period['period_key'].'.zip"');header('Content-Length:'.filesize($zipPath));readfile($zipPath);@unlink($zipPath);exit;}$pageTitle='خروجی گروهی فیش‌ها';$adminExtraStylesheets=['/assets/css/workforce.css'];$periods=Database::fetchAll('SELECT p.*,(SELECT COUNT(*) FROM payroll_slips s WHERE s.period_id=p.id) slip_count FROM payroll_periods p ORDER BY year DESC,month DESC');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>خروجی گروهی فیش‌ها</h1><p>PDF یکپارچه یا ZIP شامل PDFهای تکی</p></div><a class="btn" href="/admin/payroll-slips.php">فیش‌ها</a></div><section class="card"><form method="get" class="form-actions"><select name="period_id" required><option value="">انتخاب دوره</option><?php foreach($periods as $p):?><option value="<?=$p['id']?>" <?=$periodId===$p['id']?'selected':''?>><?=e($p['title'].' — '.$p['slip_count'].' فیش')?></option><?php endforeach?></select><button class="btn btn-primary">نمایش</button></form></section><?php if($period):?><section class="card"><h2><?=e($period['title'])?></h2><p><?=count($slips)?> فیش برای خروجی آماده است.</p><div class="form-actions"><a class="btn btn-primary" href="?period_id=<?=$periodId?>&action=group_pdf">PDF گروهی / چاپ</a><a class="btn" href="?period_id=<?=$periodId?>&action=zip">ZIP فیش‌های PDF</a></div><p class="muted">اگر کتابخانه PDF سرور نصب نباشد، خروجی گروهی به نسخه چاپ‌پسند تبدیل می‌شود. خروجی تصویر در ساختار دیتابیس پیش‌بینی شده و وابسته به کتابخانه server-side است.</p></section><?php endif?><?php require __DIR__.'/../views/partials/admin-footer.php';?>
